
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m06_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m06_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.721232449653706e+00, -2.682734114066638e+00, -2.629018543468500e+00, -2.554535286987466e+00, -2.451555128113776e+00, -2.308781852452912e+00, -2.110391009592172e+00, -1.841073325392821e+00, -1.503487269022858e+00, -1.130987137480395e+00, -6.769156652029447e-01, -4.219521060896785e-01, -4.004454235418571e-01, -3.428767149029419e-01, -2.568412016964171e-01, -1.606061552652364e-01, -8.401870363632702e-02, -4.724093198240473e-02, -1.136700681257111e-02, -1.285215166761626e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


